const transferStoreSession = `-- name: TransferStoreSession :one
SELECT id, daily_summary_id FROM public.transfer_store_session($1::uuid, $2::uuid, $3::uuid, $4::text, $5::text)
`

type TransferStoreSessionParams struct {
	TenantID     pgtype.UUID
	StoreID      pgtype.UUID
	UserID       pgtype.UUID
	ClaimCode    string
	NewClaimCode string
}

type TransferStoreSessionRow struct {
	ID             pgtype.UUID
	DailySummaryID pgtype.UUID
}

// The function locks the session, so two phones with one code cannot both take the store.
func (q *Queries) TransferStoreSession(ctx context.Context, arg TransferStoreSessionParams) (TransferStoreSessionRow, error) {
	row := q.db.QueryRow(ctx, transferStoreSession,
		arg.TenantID,
		arg.StoreID,
		arg.UserID,
		arg.ClaimCode,
		arg.NewClaimCode,
	)
	var i TransferStoreSessionRow
	err := row.Scan(&i.ID, &i.DailySummaryID)
	return i, err
}
